  [('A light with red and green costumes', 'ቀይና አረንጓዴ ልብሶች ያሉት መብራት'), ('The light changes every 3 seconds', 'መብራቱ በየ3 ሰከንዱ ይቀየራል'), ('The car: if the light is red, wait; else drive', 'መኪናው፡ መብራቱ ቀይ ከሆነ ጠብቅ፤ ካልሆነ ንዳ'), ('Add a pedestrian who crosses on red', 'በቀይ የሚሻገር እግረኛ ጨምር')],
