  ('Paper, pencil', 'ወረቀት፣ እርሳስ'),
  [('Why is a list better than ten variables?', 'list ከአሥር variables ለምን የተሻለ ነው?', 'One name holds any number of items, and one loop can go through them all.', 'አንድ ስም ማንኛውንም ቁጥር ንጥሎች ይይዛል፣ አንድ loopም ሁሉንም ሊያልፍ ይችላል።'),
   ('Your list has 5 items. You remove item 2. How long is it now?', 'listህ 5 ንጥሎች አሉት። ንጥል 2ን አስወገድክ። አሁን ርዝመቱ ስንት ነው?', '4 items, and the items after it move up one place.', '4 ንጥሎች፣ ከእሱ በኋላ ያሉት ንጥሎችም አንድ ቦታ ወደ ላይ ይንቀሳቀሳሉ።')],
  [stack(B('A list called "shopping"', '«shopping» የሚባል list'), [N('1: teff', '1፡ ጤፍ'), N('2: onions', '2፡ ሽንኩርት'), N('3: salt', '3፡ ጨው'), N('4: coffee', '4፡ ቡና')], note=B('item 3 of shopping = salt · length of shopping = 4', 'የshopping ንጥል 3 = ጨው · የshopping ርዝመት = 4'))],
